code.twist:
// Twist: swirls the angle by an amount growing with the radius (a whirlpool, turning `spin` a second) and
// winds depth round height (`wind`), so towers and spires spiral. Both in turns.
const params = {
  swirl: { value: 0.25, min: -1, max: 1, step: 0.01, label: 'Swirl (turns at the rim)' },
  wind: { value: 0, min: -1, max: 1, step: 0.01, label: 'Wind with height (turns)' },
  spin: { value: 0.05, min: -0.5, max: 0.5, step: 0.01, label: 'Turns a second' },
};

function warp(q, t, P) {
  if (P.swirl || P.spin) {
    const a = fract(q.a + P.swirl * q.r + t * P.spin);
    q.a = a;
    q.lz = 0.5 + 0.5 * q.r * sin(TAU * a);
    q.ly = 0.5 + 0.5 * q.r * cos(TAU * a);
  }
  if (P.wind) {
    const turn = TAU * P.wind * q.ly, s = sin(turn), c = cos(turn);
    const dz = q.lz - 0.5, dx = q.lx - 0.5;
    q.lz = 0.5 + dz * c - dx * s;
    q.lx = 0.5 + dz * s + dx * c;
  }
}

code.meteors:
// Meteors: shooting stars race along every strand (u, i, n place each LED on its wire), trailing fading tails.
// Each strand has its own seeded start, pace and direction (rand(p.fixture, …)), and a gap between laps.
const params = {
  speed: { value: 60, min: 5, max: 200, step: 1, label: 'LEDs per second' },
  count: { value: 2, min: 1, max: 4, step: 1, label: 'Meteors per strand' },
  tail: { value: 10, min: 2, max: 60, step: 1, label: 'Tail length (LEDs)' },
  gap: { value: 80, min: 0, max: 300, step: 1, label: 'Gap between laps (LEDs)' },
  both: { value: true, type: 'toggle', label: 'Both directions' },
  sky: { value: '#0a0a5c', type: 'color' },
  color: { value: '#00c8ff', type: 'color' },
  head: { value: '#ffffff', type: 'color' },
};

function pixel(p, t, P) {
  const s = p.fixture;
  const reverse = P.both && rand(s, 7) < 0.5;
  const i = reverse ? p.n - 1 - p.i : p.i;               // LEDs from this run's start
  const lap = p.n + P.gap;
  let v = 0;
  for (let m = 0; m < P.count; m++) {
    const pace = P.speed * (0.7 + 0.6 * rand(s, m, 3));
    const headAt = fract(rand(s, m) + t * pace / lap) * lap;
    const behind = headAt - i;                            // LEDs behind the head
    if (behind >= 0) v = max(v, exp(-behind / P.tail));
  }
  const c = mix(P.color, P.head, smoothstep(0.75, 1, v));
  return mix(P.sky, c, v);
}

code.clouds:
// Clouds: soft billows of fbm noise drift across the layer, from deep sky to bright cloud; `cover` sets how
// much sky they hide and G.energy thickens them. Mark it "input only" to mask another source with it.
const params = {
  scale: { value: 2.5, min: 0.5, max: 8, step: 0.1, label: 'Billow size (smaller is bigger)' },
  drift: { value: 0.15, min: 0, max: 1, step: 0.01, label: 'Drift speed' },
  cover: { value: 0.5, min: 0, max: 1, step: 0.01, label: 'Cloud cover' },
  sky: { value: '#0b1a4a', type: 'color' },
  cloud: { value: '#e8ecff', type: 'color' },
};

function pixel(p, t, P, G) {
  const s = t * P.drift;
  const n = fbm(p.lz * P.scale + s, p.ly * P.scale * 0.6 - s * 0.2, p.lx * P.scale * 0.5 + s * 0.3);
  const edge = 1 - clamp(P.cover + (G.energy - 0.5) * 0.3);
  const v = smoothstep(edge - 0.15, edge + 0.15, n);
  return mix(P.sky, P.cloud, v);
}

code.mask:
// Mask: shows the chain only where its input (another source here, usually "input only") is bright: past
// `cutoff` it shows, below it the alpha falls toward 1 − amount; invert masks where it is dark. No input: no-op.
const params = {
  amount: { value: 1, min: 0, max: 1, step: 0.01, label: 'Mask strength' },
  cutoff: { value: 0.35, min: 0, max: 1, step: 0.01, label: 'Brightness where it opens' },
  softness: { value: 0.3, min: 0.01, max: 1, step: 0.01, label: 'Edge softness' },
  invert: { value: false, type: 'toggle', label: 'Show where the input is dark' },
};

function filter(c, q, t, P, G, x) {
  if (!x) return c;
  const b = max(x[0], x[1], x[2]) * x[3];
  let m = smoothstep(P.cutoff - P.softness / 2, P.cutoff + P.softness / 2, b);
  if (P.invert) m = 1 - m;
  c[3] *= 1 - P.amount * (1 - m);        // c is the chain's colour: change it and hand it back
  return c;
}

code.radial-repeat:
// Radial repeat: repeats the radius r in rings round the layer's centre (lz, ly rebuilt from it and a), a tunnel
// when it zooms. rings, zoom (rings a second outward), mirror (every other ring flipped, so no seam).
const params = {
  rings: { value: 3, min: 1, max: 12, step: 1 },
  zoom: { value: 0.2, min: -2, max: 2, step: 0.01, label: 'Rings a second outward' },
  mirror: { value: true, type: 'toggle', label: 'Mirror every other ring' },
};

function warp(q, t, P) {
  const x = q.r * P.rings - t * P.zoom, r = P.mirror ? tri(x / 2) : fract(x);
  q.r = r;
  q.lz = 0.5 + 0.5 * r * sin(TAU * q.a);
  q.ly = 0.5 + 0.5 * r * cos(TAU * q.a);
}

code.mosaic:
// Mosaic: snaps positions to blocks: `cells` across width, height and depth (and metres, angle, radius to
// match), `leds` per block along each strand (1 keeps strands smooth). Flat layers stay flat.
const params = {
  cells: { value: 12, min: 2, max: 64, step: 1, label: 'Blocks across the layer' },
  leds: { value: 6, min: 1, max: 40, step: 1, label: 'LEDs per block along a strand' },
};

const snap = (v, n) => (floor(v * n) + 0.5) / n;

function warp(q, t, P) {
  const n = round(P.cells), m = round(P.leds), metres = 24 / n;
  if (q.lx !== 0.5) q.lx = snap(q.lx, n);
  q.ly = snap(q.ly, n); q.lz = snap(q.lz, n);
  q.x = snap(q.x, n); q.y = snap(q.y, n); q.z = snap(q.z, n);
  q.X = (floor(q.X / metres) + 0.5) * metres; q.Y = (floor(q.Y / metres) + 0.5) * metres;
  q.Z = (floor(q.Z / metres) + 0.5) * metres;
  q.a = snap(q.a, 2 * n); q.r = snap(q.r, n / 2);
  if (m > 1) {
    q.i = min(q.n - 1, floor(q.i / m) * m + floor(m / 2));
    q.u = q.n > 1 ? q.i / (q.n - 1) : 0;
  }
}

code.rotate:
// Rotate: turns lz and ly about the layer's centre (and the angle a with them) by `angle` turns, plus `spin`
// turns a second, so anything drawn across the layer or round it rotates.
const params = {
  angle: { value: 0.125, min: -0.5, max: 0.5, step: 0.005, label: 'Angle (turns)' },
  spin: { value: 0, min: -1, max: 1, step: 0.01, label: 'Turns a second' },
};

function warp(q, t, P) {
  const turn = P.angle + t * P.spin;
  const s = sin(TAU * turn), c = cos(TAU * turn);
  const dz = q.lz - 0.5, dy = q.ly - 0.5;
  q.lz = 0.5 + dz * c - dy * s;
  q.ly = 0.5 + dz * s + dy * c;
  q.a = fract(q.a + turn);
}

code.plasma:
// Plasma: the demoscene classic: four sines (across, up, through depth, and round a centre frame() moves) sum
// to a value that indexes a palette: 0 a full rainbow, 1-3 Inigo Quilez cosine palettes.
const params = {
  speed: { value: 0.6, min: 0, max: 3, step: 0.01 },
  scale: { value: 6, min: 1, max: 20, step: 0.1, label: 'Detail' },
  palette: { value: 0, min: 0, max: 3, step: 1 },
  drift: { value: 0.05, min: 0, max: 0.5, step: 0.01, label: 'Palette drift' },
};

let cx = 0, cy = 0, tt = 0;

function frame(t, P) {
  tt = t * P.speed;
  cx = 0.5 + 0.35 * sin(tt * 0.5);
  cy = 0.5 + 0.35 * cos(tt * 0.37);
}

function pixel(p, t, P) {
  const s = P.scale;
  let v = sin(p.lz * s * 1.3 + tt)
        + sin(p.ly * s * 1.7 - tt * 1.3)
        + sin((p.lz + p.ly + p.lx) * s * 0.9 + tt * 0.7)
        + sin(hypot(p.lz - cx, p.ly - cy) * s * 2.2 - tt * 1.1);
  v = v / 8 + 0.5 + t * P.drift;
  switch (round(P.palette)) {
    case 1: return cosPalette(v, [0.5, 0.5, 0.5], [0.5, 0.5, 0.5], [1, 1, 0.5], [0.8, 0.9, 0.3]);
    case 2: return cosPalette(v, [0.5, 0.5, 0.5], [0.5, 0.5, 0.5], [1, 0.7, 0.4], [0, 0.15, 0.2]);
    case 3: return cosPalette(v, [0.5, 0.5, 0.5], [0.5, 0.5, 0.5], [2, 1, 0], [0.5, 0.2, 0.25]);
    default: return hsv(v, 1, 1);
  }
}

code.gradient-map:
// Gradient map: recolours the chain by luminance across the whole palette, low for the dark through body and
// accent to the highlight. amount, contrast, shift (along the palette), drift (a second; walks back at the ends).
const params = {
  amount: { value: 1, min: 0, max: 1, step: 0.01 },
  contrast: { value: 1.2, min: 0.2, max: 4, step: 0.05 },
  shift: { value: 0, min: -1, max: 1, step: 0.01, label: 'Slide along the palette' },
  drift: { value: 0, min: -0.5, max: 0.5, step: 0.01, label: 'Slide a second' },
};

function filter(c, q, t, P) {
  const v = 0.2126 * c[0] + 0.7152 * c[1] + 0.0722 * c[2];
  const m = palette(tri(((v - 0.5) * P.contrast + 0.5 + P.shift + t * P.drift) / 2));
  for (let i = 0; i < 3; i++) c[i] = mix(c[i], m[i], P.amount);
  return c;
}

code.hue-shift:
// Hue shift: turns colours round the wheel (round the grey axis, so brightness holds) by place along an axis:
// across, up, front to back, round (a) or along strands (u). spread (turns over it), speed (turns a second).
const params = {
  spread: { value: 0.5, min: -2, max: 2, step: 0.01, label: 'Turns of hue across the axis' },
  axis: { value: 0, min: 0, max: 4, step: 1, label: 'Across, up, front → back, round, along' },
  speed: { value: 0.05, min: -1, max: 1, step: 0.01, label: 'Turns a second' },
};

function filter(c, q, t, P) {
  const a = round(P.axis), x = a === 0 ? q.lz : a === 1 ? q.ly : a === 2 ? q.lx : a === 3 ? q.a : q.u;
  const turn = TAU * (x * P.spread + t * P.speed), cs = cos(turn), s = sin(turn) / sqrt(3), k = (1 - cs) / 3;
  const r = c[0], g = c[1], b = c[2];
  c[0] = clamp(r * (cs + k) + g * (k - s) + b * (k + s));
  c[1] = clamp(r * (k + s) + g * (cs + k) + b * (k - s));
  c[2] = clamp(r * (k - s) + g * (k + s) + b * (cs + k));
  return c;
}

code.sparkle:
// Sparkle: seeded highlight glints added as light on top of the chain, like frost; a glint lights alpha too.
// density (share of LEDs, by rand(p.k); more with energy), rate (glints a second), length.
const params = {
  density: { value: 0.3, min: 0, max: 1, step: 0.01, label: 'Share of LEDs that glint' },
  rate: { value: 0.6, min: 0.05, max: 4, step: 0.01, label: 'Glints a second' },
  length: { value: 0.15, min: 0.02, max: 0.5, step: 0.01, label: 'Glint length' },
};

function filter(c, q, t, P, G) {
  if (rand(q.k, 11) > P.density * (0.5 + G.energy)) return c;
  const g = pulse(rand(q.k, 12) * 9.7 + t * P.rate * (0.5 + rand(q.k, 13)), P.length);
  if (g <= 0) return c;
  const h = pal('high'), A = max(c[3], g);
  for (let i = 0; i < 3; i++) c[i] = min(1, (c[i] * c[3] + h[i] * g) / A);
  c[3] = A;
  return c;
}

code.edge-fade:
// Edge fade: fades the chain's alpha toward the layer's edges, so it melts into what is below. axis (across,
// up, front to back, out from the centre), width, oneSide (on `up`: from the ground), invert.
const params = {
  axis: { value: 1, min: 0, max: 3, step: 1, label: 'Across, up, front → back, out from the centre' },
  width: { value: 0.35, min: 0.02, max: 1, step: 0.01, label: 'Fade reach' },
  oneSide: { value: true, type: 'toggle', label: 'From one side only' },
  invert: { value: false, type: 'toggle', label: 'Fade the middle instead' },
};

function filter(c, q, t, P) {
  const a = round(P.axis), x = a === 0 ? q.lz : a === 1 ? q.ly : a === 2 ? q.lx : 1 - q.r;
  let k = smoothstep(0, P.width, x);
  if (!P.oneSide && a < 3) k *= smoothstep(0, P.width, 1 - x);
  c[3] *= P.invert ? 1 - k : k;
  return c;
}

code.mirror:
// Mirror: folds the layer onto itself before the modules after it draw: left-right (lz, z, a), front-back
// (lx, x), up-down (ly, y), or every wire at its middle (u, i), so chases run in from both ends.
const params = {
  leftRight: { value: true, type: 'toggle', label: 'Left ↔ right' },
  frontBack: { value: false, type: 'toggle', label: 'Front ↔ back' },
  upDown: { value: false, type: 'toggle', label: 'Up ↔ down' },
  along: { value: false, type: 'toggle', label: 'Along strands' },
};

const fold = (v) => (v > 0.5 ? 1 - v : v);

function warp(q, t, P) {
  if (P.leftRight) { q.lz = fold(q.lz); q.z = fold(q.z); q.a = fold(q.a); }
  if (P.frontBack) { q.lx = fold(q.lx); q.x = fold(q.x); }
  if (P.upDown) { q.ly = fold(q.ly); q.y = fold(q.y); }
  if (P.along) { q.u = fold(q.u); q.i = min(q.i, q.n - 1 - q.i); }
}

code.kaleidoscope:
// Kaleidoscope: folds the angle a into `segments` mirrored wedges round the layer's centre, turning `spin`
// turns a second; lz and ly are rebuilt from the folded angle and r, so sources drawn across repeat too.
const params = {
  segments: { value: 6, min: 2, max: 16, step: 1, label: 'Wedges' },
  spin: { value: 0.02, min: -0.5, max: 0.5, step: 0.01, label: 'Turns a second' },
};

function warp(q, t, P) {
  const seg = 1 / max(2, round(P.segments));
  const f = fract((q.a + t * P.spin) / seg);
  const a = (f < 0.5 ? f : 1 - f) * seg;          // within the first wedge, mirrored back and forth
  q.a = a;
  q.lz = 0.5 + 0.5 * q.r * sin(TAU * a);
  q.ly = 0.5 + 0.5 * q.r * cos(TAU * a);
}

code.scroll:
// Scroll: slides the layer, wrapping round: across, up, front to back (layer widths a second) or along every
// strand (u and i together, so chases drawn after it drift along their wires).
const params = {
  across: { value: 0.1, min: -2, max: 2, step: 0.01, label: 'Left → right' },
  up: { value: 0, min: -2, max: 2, step: 0.01, label: 'Upward' },
  depth: { value: 0, min: -2, max: 2, step: 0.01, label: 'Front → back' },
  along: { value: 0, min: -2, max: 2, step: 0.01, label: 'Along strands' },
};

function warp(q, t, P) {
  if (P.across) q.lz = fract(q.lz - t * P.across);
  if (P.up) q.ly = fract(q.ly - t * P.up);
  if (P.depth) q.lx = fract(q.lx - t * P.depth);
  if (P.along) {
    q.u = fract(q.u - t * P.along);
    q.i = round(q.u * (q.n - 1));
  }
}

code.trails:
// Trails: a fading afterglow behind whatever moves. A buffer by p.k remembers each LED's light, decaying to
// `decay` after a second; the chain shows the brighter of now and what is left. Time going back clears it.
const params = {
  decay: { value: 0.15, min: 0, max: 0.95, step: 0.01, label: 'Left after one second' },
};

let mem = new Float32Array(3 * 5000);
let last = NaN, keep = 0;

function frame(t, P) {
  const dt = t - last;
  keep = dt > 0 && dt < 1 ? pow(P.decay, dt) : 0;
  last = t;
}

function filter(c, q, t, P) {
  const o = 3 * q.k;
  if (o + 2 >= mem.length) {             // more LEDs than expected: grow once
    const more = new Float32Array(o + 3000);
    more.set(mem);
    mem = more;
  }
  for (let i = 0; i < 3; i++) {
    const now = c[i] * c[3], held = mem[o + i] * keep;
    c[i] = mem[o + i] = now > held ? now : held;
  }
  c[3] = 1;
  return c;
}

code.palette-drift:
// Palette drift: a calm bed of full-strength colour whose hues travel slowly, varying with depth, height and
// a soft fbm swirl. A good bottom layer to stack sweeps, sparkles or chases on.
const params = {
  hue: { value: 0.6, min: 0, max: 1, step: 0.01, label: 'Starting hue' },
  drift: { value: 0.02, min: 0, max: 0.2, step: 0.005, label: 'Hue turns per second' },
  spread: { value: 0.25, min: 0, max: 1, step: 0.01, label: 'Hue spread across the layer' },
  swirl: { value: 0.12, min: 0, max: 0.5, step: 0.01 },
  saturation: { value: 1, min: 0.5, max: 1, step: 0.01 },
};

function pixel(p, t, P) {
  const h = P.hue + t * P.drift
          + P.spread * (0.6 * p.lx + 0.4 * p.ly)
          + P.swirl * (fbm(p.lx * 2, p.ly * 2, p.lz * 2 + t * 0.05) - 0.5);
  return hsv(h, P.saturation, 1);
}

code.tint:
// Tint: recolours the chain from one role of the look's palette, keeping its light and shade: brightness walks
// along the role (pal(role, t)), so the look follows whichever palette is picked. amount blends.
const params = {
  role: { value: 1, min: 0, max: 3, step: 1, label: 'Role: low, body, accent, high' },
  amount: { value: 1, min: 0, max: 1, step: 0.01 },
  spread: { value: 1, min: 0, max: 1, step: 0.01, label: 'How far brightness walks the role' },
};
const ROLES = ['low', 'body', 'accent', 'high'];

function filter(c, q, t, P) {
  const v = max(c[0], c[1], c[2]);
  const tint = pal(ROLES[clamp(round(P.role), 0, 3)], v * P.spread);
  for (let i = 0; i < 3; i++) c[i] = mix(c[i], tint[i] * v, P.amount);
  return c;
}

code.blur:
// Blur: softens the chain's colour across neighbouring LEDs, along each strand (wire), through space, or both: hard
// edges melt, a chase glows. The core runs it over the whole layer at once (SPEC "Spatial modules"), counting only
// this layer's LEDs; filter() is what a core without spatial modules does. radius (metres), mode, amount.
const spatial = 'blur';
const params = {
  radius: { value: 0.4, min: 0, max: 1.5, step: 0.01, label: 'Radius (metres; along the wire, metres of wire)' },
  mode: { value: 'space', type: 'choice', options: ['wire', 'space', 'both'], label: 'Along the wire, in space, both' },
  amount: { value: 1, min: 0, max: 1, step: 0.01, label: 'Mix with the sharp colour' },
};

function filter(c) {
  return c;
}

code.counted:
let calls = 0;
function frame() { calls++; }
function pixel(p) { return [p.lz, calls % 7 / 7, p.ly]; }

code.rising-sweep:
// Rising sweep: bands of colour climb every surface like a tide (ly is height across the layer's own
// pixels), trading the base colour for the sweep colour; nothing goes dark. Width down for thin bars.
const params = {
  speed: { value: 0.25, min: 0, max: 2, step: 0.01, label: 'Sweeps per second' },
  bands: { value: 1, min: 1, max: 6, step: 1, label: 'Bands at once' },
  width: { value: 0.5, min: 0.02, max: 1, step: 0.01, label: 'Bar width' },
  base: { value: '#2a00ff', type: 'color' },
  sweep: { value: '#ff1f6a', type: 'color' },
  down: { value: false, type: 'toggle', label: 'Fall instead of rise' },
};

function pixel(p, t, P) {
  const h = P.down ? 1 - p.ly : p.ly;
  // Distance from the nearest bar centre, in bands: 0 on the centre line, 0.5 between bars.
  const d = abs(fract(h * P.bands - t * P.speed + 0.5) - 0.5);
  const half = P.width / 2;
  const k = 1 - smoothstep(half - 0.04, half + 0.04, d);
  return mix(P.base, P.sweep, k);
}

code.disc:
function pixel(p, t) {
  const a = smoothstep(0.75, 0.25, p.r) * (0.5 + 0.5 * sin(TAU * (3 * p.a - t)));
  return [0.9, 0.3 + 0.5 * p.a, 0.1, a];
}

code.threshold:
// Threshold: lights only what is brighter (its brightest channel) than `level`, with a soft edge, so busy
// textures become crisp shapes; kept parts keep their colour, or take `color` with recolour on.
const params = {
  level: { value: 0.5, min: 0, max: 1, step: 0.01 },
  softness: { value: 0.05, min: 0, max: 0.5, step: 0.01, label: 'Edge softness' },
  recolour: { value: false, type: 'toggle', label: 'One colour for what is kept' },
  color: { value: '#ffd27a', type: 'color' },
};

function filter(c, q, t, P) {
  const v = max(c[0], c[1], c[2]);
  const k = P.softness > 0 ? smoothstep(P.level - P.softness, P.level + P.softness, v) : step(P.level, v);
  for (let i = 0; i < 3; i++) c[i] = (P.recolour ? P.color[i] : c[i]) * k;
  return c;
}

code.aurora:
// Aurora: slow curtains of green and violet over a night-blue sky, never black. Fractal noise (fbm) across
// width and depth places the curtains, a finer noise stretched upward draws their rays, height walks the colour.
const params = {
  speed: { value: 1, min: 0, max: 4, step: 0.05 },
  amount: { value: 0.55, min: 0, max: 1, step: 0.01, label: 'How much sky the curtains cover' },
  sky: { value: '#06104a', type: 'color' },
  low: { value: '#00ff6a', type: 'color' },
  mid: { value: '#00d0ff', type: 'color' },
  high: { value: '#b000ff', type: 'color' },
};

function pixel(p, t, P) {
  const s = t * P.speed;
  const n = fbm(p.lz * 2 + s * 0.06, p.lx * 2 - s * 0.03, s * 0.05);
  const edge = 1 - P.amount;
  const curtain = smoothstep(edge - 0.12, edge + 0.12, n);
  const rays = noise(p.lz * 16 + n * 6, p.lx * 4, s * 0.25);
  const glow = curtain * (0.5 + 0.5 * rays);
  const c = gradient(clamp(p.ly * 0.85 + (n - 0.5) * 0.8), [P.low, P.mid, P.high]);
  return mix(P.sky, c, glow);
}

code.fireworks:
// Fireworks: shells burst high into rings of sparks that sag and fade, body or accent with a white-hot heart,
// over a night of the low colour at `sky`. every (seconds per slot; energy fills more slots), size, sparks.
const params = {
  every: { value: 2.2, min: 0.8, max: 8, step: 0.1, label: 'Seconds between bursts (each slot)' },
  size: { value: 0.34, min: 0.1, max: 0.6, step: 0.01, label: 'Burst radius' },
  sparks: { value: 12, min: 4, max: 32, step: 1, label: 'Sparks round a burst' },
  sky: { value: 0.35, min: 0, max: 1, step: 0.01, label: 'Sky brightness' },
};

const SLOTS = 6;
const CZ = new Float64Array(SLOTS), CY = new Float64Array(SLOTS), AGE = new Float64Array(SLOTS);
const ID = new Float64Array(SLOTS);
let on = 0;

function frame(t, P, G) {
  on = 2 + round(G.energy * 4);
  for (let s = 0; s < on; s++) {
    const x = t / P.every + rand(s, 9), c = floor(x), a = (x - c) * P.every;
    ID[s] = c * SLOTS + s;
    AGE[s] = a;
    CZ[s] = 0.15 + 0.7 * rand(s, c, 1);
    CY[s] = 0.5 + 0.35 * rand(s, c, 2) - 0.05 * a * a;          // the burst sags as it falls
  }
}

function pixel(p, t, P) {
  let c = scale(pal('low', p.ly), P.sky);
  for (let s = 0; s < on; s++) {
    const a = AGE[s], R = P.size * (1 - exp(-a * 3));
    const dz = p.lz - CZ[s], dy = p.ly - CY[s], d = hypot(dz, dy);
    if (d > R + 0.03) continue;
    const spark = pulse(atan2(dz, dy) / TAU * P.sparks + rand(ID[s], 3), 0.45);
    const v = (spark * smoothstep(R * 0.2, R, d) + 0.25) * exp(-a * 0.9) + exp(-d * d * 300 - a * 6);
    const hue = ID[s] % 2 ? pal('accent', rand(ID[s], 4)) : pal('body', rand(ID[s], 5));
    c = mix(c, mix(hue, pal('high'), exp(-a * 5)), min(1, v * 1.5));
  }
  return c;
}

code.bars:
// Bars: bands of body and accent colour march across the layer edge to edge (xLights' Bars). speed (plus
// energy, via frame()'s clock), bars, direction (up, down, across, front to back, out, in), softness (each edge).
const params = {
  speed: { value: 0.4, min: -2, max: 2, step: 0.01, label: 'Bars a second' },
  bars: { value: 4, min: 1, max: 16, step: 1, label: 'Bars across the layer' },
  direction: { value: 0, min: 0, max: 6, step: 1, label: 'Up, down, →, ←, front → back, out, in' },
  softness: { value: 0.2, min: 0, max: 1, step: 0.01, label: 'Edge softness (share of a bar)' },
};

let run = 0, last = 0;
function frame(t, P, G) {
  const dt = t - last, k = P.speed * (0.5 + G.energy);
  run = dt >= 0 && dt < 1 ? run + dt * k : t * k;
  last = t;
}

// The i-th band: body and accent colours in turn, spread along each role.
const swatch = (i) => pal(i & 1 ? 'accent' : 'body', fract(i * 0.618));

function pixel(p, t, P, G) {
  const d = round(P.direction), mid = min(1, hypot(p.lz - 0.5, p.ly - 0.5) * 2);
  const x = d === 0 ? p.ly : d === 1 ? 1 - p.ly : d === 2 ? p.lz : d === 3 ? 1 - p.lz : d === 4 ? p.lx
    : d === 5 ? mid : 1 - mid;
  const f = x * P.bars - run, b = round(f);                 // b: the nearest edge, bar b − 1 below it, bar b above
  return mix(swatch(b - 1), swatch(b), soft(b, f, P.softness));
}

code.lighthouse:
// Lighthouse: beams turn round the layer's vertical axis (atan2 of lz and lx; a flat layer, lx 0.5 all over,
// turns in the façade by a), each a solid band of saturated colour with a crisp `edge`, never blended toward
// white, leaving an afterglow (`glow`) through the trail colour. twist winds the beams with height.
const params = {
  speed: { value: 0.2, min: -2, max: 2, step: 0.01, label: 'Turns per second' },
  beams: { value: 2, min: 1, max: 6, step: 1 },
  width: { value: 0.22, min: 0.02, max: 0.5, step: 0.01, label: 'Beam width (share of the gap)' },
  edge: { value: 0.015, min: 0.002, max: 0.2, step: 0.001, label: 'Edge softness' },
  glow: { value: 0.55, min: 0, max: 1, step: 0.01, label: 'Afterglow behind the beam' },
  twist: { value: 0, min: -2, max: 2, step: 0.05, label: 'Twist with height' },
  base: { value: '#14009e', type: 'color' },
  trail: { value: '#d4006a', type: 'color' },
  beam: { value: '#ffae00', type: 'color' },
};

let turn = 0;

function frame(t, P) {
  turn = t * P.speed;
}

function pixel(p, t, P) {
  const flat = p.lx === 0.5;
  const angle = (flat ? p.a : atan2(p.lz - 0.5, p.lx - 0.5) / TAU) + p.ly * P.twist;
  const s = fract((angle - turn) * P.beams);              // 0 on a beam's centre line, rising ahead of it
  const half = P.width / 2, d = min(s, 1 - s);
  const behind = (P.speed < 0 ? s : 1 - s) - half;        // how far the beam has passed this LED
  const after = behind > 0 && behind < 0.5 ? P.glow * exp(-behind * 8) : 0;
  const c = mix(P.base, P.trail, after);
  return mix(c, P.beam, smoothstep(half + P.edge, half, d));
}

code.galaxy:
// Galaxy: spiral arms wheel round a highlight core by a and r round the layer's centre, accent near the core,
// body at the rim (xLights). speed (turns a second, plus energy), arms, twist (turns core to rim), width.
const params = {
  speed: { value: 0.1, min: -1, max: 1, step: 0.01, label: 'Turns a second' },
  arms: { value: 3, min: 1, max: 8, step: 1 },
  twist: { value: 1.2, min: -4, max: 4, step: 0.05, label: 'Wind (turns from core to rim)' },
  width: { value: 0.3, min: 0.05, max: 0.5, step: 0.01, label: 'Arm width' },
};

let spin = 0, last = 0;
function frame(t, P, G) {
  const dt = t - last, k = P.speed * (0.5 + G.energy);
  spin = dt >= 0 && dt < 1 ? spin + dt * k : t * k;
  last = t;
}

function pixel(p, t, P) {
  const arm = pulse((p.a - p.r * P.twist - spin) * P.arms, P.width) * (1 - 0.4 * p.r);
  const glow = mix(pal('accent', p.r), pal('body', p.r), smoothstep(0.2, 0.8, p.r));
  const c = mix(pal('low', p.r), glow, arm);
  return mix(c, pal('high'), exp(-p.r * p.r * 60));
}
